import sqlite3
from datetime import date
from pathlib import Path


CONTRACT = "FC-DES-1500J-05919"
FACILITY = "FAC-DES-1500J"
MASTER_CONTRACT = "CTR-DES-05919"
CONTRACTOR = "CON-SMS-001"
INSPECTORS = {
    ("EMP-DES-1042", "M. Alvarez"),
    ("EMP-DES-1178", "J. Patel"),
}


def _workspace_path(ws):
    return Path(ws) if isinstance(ws, (str, Path)) else Path(getattr(ws, "path", ws))


def _db_path(ws):
    return _workspace_path(ws).parent / "system" / "des_quality_inspections" / "state.db"


def _backup_path(ws):
    return _workspace_path(ws).parent / "system" / "des_quality_inspections" / "state.db.pinned_backup"


def _connect(path):
    con = sqlite3.connect(path)
    con.row_factory = sqlite3.Row
    return con


def _rows(con, table):
    return [dict(row) for row in con.execute(f"SELECT * FROM {table} ORDER BY rowid")]


def check_scheduled_session_postcondition(ws):
    try:
        with _connect(_db_path(ws)) as con, _connect(_backup_path(ws)) as base:
            base_ids = {
                row[0]
                for row in base.execute(
                    "SELECT inspection_id FROM inspection_sessions WHERE facility_contract_id = ?",
                    (CONTRACT,),
                )
            }
            new_rows = [
                dict(row) for row in con.execute(
                    "SELECT * FROM inspection_sessions WHERE facility_contract_id = ? "
                    "AND inspection_id NOT IN (%s)"
                    % ",".join("?" for _ in base_ids),
                    (CONTRACT, *base_ids),
                )
            ] if base_ids else [dict(row) for row in con.execute("SELECT * FROM inspection_sessions")]
            if len(new_rows) != 1:
                return {"score": 0, "detail": f"expected exactly one new session, found {len(new_rows)}"}
            row = new_rows[0]
            contract = con.execute(
                "SELECT contract_start_date, contract_end_date FROM facility_service_contracts "
                "WHERE facility_contract_id = ? AND facility_id = ? AND contract_id = ? AND contractor_id = ?",
                (CONTRACT, FACILITY, MASTER_CONTRACT, CONTRACTOR),
            ).fetchone()
            if contract is None:
                return {"score": 0, "detail": "required facility contract join is missing"}
            scheduled_date = date.fromisoformat(row["inspection_date"])
            context = (row["complaint_context"] or "").lower()
            checks = {
                "facility_contract_id": row["facility_contract_id"] == CONTRACT,
                "facility_id": row["facility_id"] == FACILITY,
                "contract_id": row["contract_id"] == MASTER_CONTRACT,
                "contractor_id": row["contractor_id"] == CONTRACTOR,
                "status": row["inspection_status"] == "scheduled",
                "weekday": scheduled_date.weekday() < 5,
                "inside_contract_term": contract["contract_start_date"] <= row["inspection_date"] <= contract["contract_end_date"],
                "inspector": (row["inspector_employee_id"], row["inspector_name"]) in INSPECTORS,
                "unique_reference": bool(row["inspection_reference_id"]) and con.execute(
                    "SELECT COUNT(*) FROM inspection_sessions WHERE inspection_reference_id = ?",
                    (row["inspection_reference_id"],),
                ).fetchone()[0] == 1,
                "header_score_zero": abs(float(row["session_score_pct"])) <= 1e-9,
                "window_context": "window" in context and "wash" in context,
                "complaint_context": "complaint" in context,
            }
            failed = [name for name, passed in checks.items() if not passed]
            if failed:
                return {"score": 0, "detail": "failed: " + ", ".join(failed)}
            return {"score": 1, "detail": "one valid new scheduled session: " + row["inspection_reference_id"]}
    except Exception as exc:
        return {"score": 0, "detail": f"verification error: {exc}"}


def check_historical_rows_unchanged(ws):
    try:
        with _connect(_db_path(ws)) as con, _connect(_backup_path(ws)) as base:
            for table in ("inspection_sessions", "inspection_observation_lots", "facility_service_contracts"):
                if table == "inspection_sessions":
                    current = [dict(row) for row in con.execute(
                        "SELECT * FROM inspection_sessions WHERE facility_contract_id = ? ORDER BY inspection_id",
                        (CONTRACT,),
                    )]
                    original = [dict(row) for row in base.execute(
                        "SELECT * FROM inspection_sessions WHERE facility_contract_id = ? ORDER BY inspection_id",
                        (CONTRACT,),
                    )]
                elif table == "inspection_observation_lots":
                    current = [dict(row) for row in con.execute(
                        "SELECT * FROM inspection_observation_lots WHERE facility_contract_id = ? ORDER BY observation_lot_id",
                        (CONTRACT,),
                    )]
                    original = [dict(row) for row in base.execute(
                        "SELECT * FROM inspection_observation_lots WHERE facility_contract_id = ? ORDER BY observation_lot_id",
                        (CONTRACT,),
                    )]
                else:
                    current = [dict(row) for row in con.execute(
                        "SELECT * FROM facility_service_contracts WHERE facility_contract_id = ? ORDER BY facility_contract_id",
                        (CONTRACT,),
                    )]
                    original = [dict(row) for row in base.execute(
                        "SELECT * FROM facility_service_contracts WHERE facility_contract_id = ? ORDER BY facility_contract_id",
                        (CONTRACT,),
                    )]
                if table == "inspection_sessions":
                    original_by_id = {row["inspection_id"]: row for row in original}
                    for row in current:
                        if row["inspection_id"] in original_by_id and row != original_by_id[row["inspection_id"]]:
                            return {"score": 0, "detail": f"pre-existing {table} row changed: {row['inspection_id']}"}
                    if not set(original_by_id).issubset({row["inspection_id"] for row in current}):
                        return {"score": 0, "detail": f"pre-existing {table} row deleted"}
                elif current != original:
                    return {"score": 0, "detail": f"historical {table} rows changed"}
            return {"score": 1, "detail": "historical sessions, observation lots, and contract row preserved"}
    except Exception as exc:
        return {"score": 0, "detail": f"verification error: {exc}"}
